#pragma once
#include <chrono>
#include <cstdio>
#include <cstdint>
namespace hvf_phase_profile {
enum Phase { Submit, Owner, Prepare, Capture, Native, Run, Count };
struct Record { uint64_t Count = 0, Ns = 0; };
struct Totals {
  Record Records[Count]{};
  ~Totals() {
    const char *Names[] = {"submit", "owner", "prepare", "capture", "native", "run"};
    for (unsigned I = 0; I < Count; ++I)
      if (Records[I].Count)
        std::fprintf(stderr, "{\"diagnostic_phase\":\"%s\",\"count\":%llu,\"inclusive_ns\":%llu}\n", Names[I], (unsigned long long)Records[I].Count, (unsigned long long)Records[I].Ns);
  }
};
inline thread_local Totals Values;
struct Scope {
  using Clock = std::chrono::steady_clock;
  Phase Value;
  Clock::time_point Begin;
  explicit Scope(Phase Value) : Value(Value), Begin(Clock::now()) {}
  ~Scope() {
    auto &R = Values.Records[Value];
    ++R.Count;
    R.Ns += std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now() - Begin).count();
  }
};
}

